$error=is_string($error??null)?$error:'';$csrf=is_string($csrf??null)?$csrf:'';
$brandName=is_string($brandName??null)?$brandName:'Talyvane';
$escape=static fn(mixed $value):string=>htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Client model distribution · <?= $escape($brandName) ?></title>
<style>
:root{color-scheme:light;--ink:#182638;--muted:#667487;--paper:#f4f2ed;--line:#e6e2d9;--navy:#142235;--accent:#8a653f}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.6 system-ui,sans-serif}.shell{width:min(1100px,calc(100% - 32px));margin:auto}.top{padding:22px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.panel{background:#fffefa;border:1px solid var(--line);padding:20px;margin:22px 0}h1{font:400 40px Georgia,serif;margin:32px 0 8px}.muted{color:var(--muted)}.alert{padding:12px;background:#fff4f2;border:1px solid #e9c9c4;color:#8b3535;margin:18px 0}.row{display:grid;grid-template-columns:minmax(0,1fr) minmax(240px,360px);gap:16px;padding:14px 0;border-bottom:1px solid var(--line)}select,button{font:inherit;padding:9px;border:1px solid var(--line)}button{background:var(--navy);color:#fff;border:0;cursor:pointer}.small{font-size:12px;color:var(--muted)}@media(max-width:700px){.row{grid-template-columns:1fr}}
</style></head><body><header class="shell top"><strong><?= $escape($brandName) ?> · Model distribution</strong><a href="/admin/model-agency">Agency operations</a></header><main class="shell"><h1>Client distribution</h1><p class="muted">Link casting briefs and assignments to a single active, email-verified client-only account. Existing free-form client names are never used to infer account ownership. Distribution remains read-only for clients; candidate images are re-authorized at every request.</p>
